<?php use App\Core\Csrf; use App\Helpers\ViewHelper; $status = (string)$order['status']; ?>
<div class="container page-head"><p class="eyebrow">Tài khoản</p><h1>Chi tiết đơn hàng</h1><p class="lead">Mã đơn: <?= ViewHelper::escape((string)$order['order_code']) ?></p></div>
<section class="container section order-detail-layout">
    <article class="info-card"><div class="section-heading"><div><p class="eyebrow">Trạng thái</p><h2><?= ViewHelper::escape(ViewHelper::orderStatus($status)) ?></h2></div><span class="report-badge report-badge-neutral"><?= ViewHelper::escape($order['created_at']) ?></span></div>
        <h3>Sản phẩm</h3><ul class="order-products order-detail-products"><?php foreach ($order['items'] as $item): ?><li><span><?= ViewHelper::escape($item['book_title']) ?> × <?= (int)$item['quantity'] ?></span><strong><?= ViewHelper::money((int)$item['line_total']) ?></strong></li><?php endforeach; ?></ul>
        <div class="order-total-row"><span>Tổng tiền</span><strong><?= ViewHelper::money((int)$order['total']) ?></strong></div>
    </article>
    <aside class="info-card"><h2>Thông tin nhận hàng</h2><p><strong><?= ViewHelper::escape($order['shipping_name']) ?></strong><br><?= ViewHelper::escape($order['shipping_phone']) ?><br><?= ViewHelper::escape($order['shipping_email']) ?><br><?= ViewHelper::escape($order['shipping_address']) ?></p><p>Thanh toán: <?= ViewHelper::escape(ViewHelper::paymentMethod((string)$order['payment_method'])) ?><br>Trạng thái: <?= ViewHelper::escape(ViewHelper::paymentStatus((string)$order['payment_status'])) ?></p></aside>
</section>
<section class="container section order-actions">
<?php if (in_array($status, ['pending', 'confirmed'], true)): ?><form class="form-card" method="post" action="/orders/<?= (int)$order['id'] ?>/cancel"><?= Csrf::field() ?><h2><?= $status === 'pending' ? 'Hủy đơn hàng' : 'Yêu cầu hủy đơn hàng' ?></h2><label for="cancel-reason">Lý do hủy</label><textarea id="cancel-reason" name="reason" rows="3" required></textarea><button class="button button-danger" type="submit">Gửi yêu cầu hủy</button></form><?php endif; ?>
<?php if ($status === 'delivered'): ?><form class="form-card" method="post" action="/orders/<?= (int)$order['id'] ?>/confirm-received"><?= Csrf::field() ?><h2>Xác nhận đã nhận hàng</h2><p>Đơn hàng sẽ chuyển sang hoàn tất và được tính vào doanh thu.</p><button class="button button-primary" type="submit">Tôi đã nhận được hàng</button></form><form class="form-card" method="post" action="/orders/<?= (int)$order['id'] ?>/return" enctype="multipart/form-data"><?= Csrf::field() ?><h2>Yêu cầu đổi trả</h2><label for="return-reason">Lý do đổi trả</label><textarea id="return-reason" name="reason" rows="3" required></textarea><label for="return-image">Hình ảnh sản phẩm</label><input id="return-image" name="return_image" type="file" accept="image/jpeg,image/png,image/webp" required><button class="button" type="submit">Gửi yêu cầu đổi trả</button></form><?php endif; ?>
<?php if ($status === 'cancel_requested'): ?><div class="notice">Yêu cầu hủy đang chờ Admin xác nhận.</div><?php endif; ?><?php if ($status === 'return_requested'): ?><div class="notice">Yêu cầu đổi trả đang được Admin kiểm tra.</div><?php endif; ?><?php if (!empty($order['cancel_reason'])): ?><div class="notice">Lý do hủy: <?= ViewHelper::escape((string)$order['cancel_reason']) ?></div><?php endif; ?><?php if (!empty($order['return_review_reason'])): ?><div class="notice">Ghi chú đổi trả: <?= ViewHelper::escape((string)$order['return_review_reason']) ?></div><?php endif; ?>
</section>
<section class="container section"><article class="info-card"><h2>Lịch sử xử lý</h2><ul class="order-timeline"><?php foreach ($order['history'] as $history): ?><li><strong><?= ViewHelper::escape(ViewHelper::orderStatus((string)$history['to_status'])) ?></strong><span><?= ViewHelper::escape((string)$history['note']) ?> · <?= ViewHelper::escape((string)$history['created_at']) ?></span></li><?php endforeach; ?></ul></article></section>
